validate_raster_against_template <- function(raster,template,value_range=c(-100,70),exact_geometry=TRUE) { r <- tryCatch(if(is.character(raster)) terra::rast(raster) else raster,error=function(e)e); if(inherits(r,"error")) return(list(valid=FALSE,message=conditionMessage(r))); if(terra::nlyr(r)!=1) return(list(valid=FALSE,message="expected one layer")); if(exact_geometry) { same<-identical(terra::crs(r),terra::crs(template))&&all(abs(as.vector(terra::ext(r))-as.vector(terra::ext(template)))<1e-9)&&all(abs(as.numeric(terra::res(r))-as.numeric(terra::res(template)))<1e-9)&&terra::nrow(r)==terra::nrow(template)&&terra::ncol(r)==terra::ncol(template)&&all(abs(as.numeric(terra::origin(r))-as.numeric(terra::origin(template)))<1e-9); if(!same) return(list(valid=FALSE,message="geometry does not match template")) }; v <- terra::values(r,mat=FALSE); v <- v[is.finite(v)]; if(!length(v)) return(list(valid=FALSE,message="all values are NA")); if(any(v<value_range[1]||v>value_range[2])) return(list(valid=FALSE,message="values outside configured range")); list(valid=TRUE,message="ok",minimum=min(v),maximum=max(v),n=length(v)) }
validate_daily_output <- function(path,expected_date,template,config) { p <- parse_grid_filename(path,config$project$output_prefix); if(!p$valid||p$timestep!="daily"||p$date!=as.Date(expected_date)) return(list(valid=FALSE,message="filename date mismatch")); validate_raster_against_template(path,template,c(config$validation$minimum_celsius,config$validation$maximum_celsius),config$validation$require_exact_template_geometry) }
validate_weekly_output <- function(path,expected_iso_year,expected_iso_week,template,config) { p <- parse_grid_filename(path,config$project$output_prefix); if(!p$valid||p$timestep!="weekly"||p$iso_year!=as.integer(expected_iso_year)||p$iso_week!=as.integer(expected_iso_week)) return(list(valid=FALSE,message="filename week mismatch")); validate_raster_against_template(path,template,c(config$validation$minimum_celsius,config$validation$maximum_celsius),config$validation$require_exact_template_geometry) }
